const $=id=>document.getElementById(id),proxyServer=location.protocol.startsWith('http'),api=proxyServer?'/api/nhl/v1':'https://api-web.nhle.com/v1',searchApi=proxyServer?'/api/player-search':'https://search.d3.nhle.com/api/v1/search/player',cache=new Map(),playerSelections={stats:null,history:null};
const dateStr=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
