 const players=[...new Map(rosters.flatMap(x=>x.players).map(p=>[p.id,p])).values()];if(!players.length)throw Error('Could not load skater rosters for this slate.');status('picksStatus',`Comparing ${players.length} skaters across ${games.length} games · loading two seasons of game logs…`);
