  const candidates=[];for(const game of games){const home=game.homeTeam?.abbrev,away=game.awayTeam?.abbrev;for(const player of players.filter(p=>p.team===home||p.team===away)){const opp=player.team===home?away:home,[currentAll,prior]=logData.get(player.id)||[[],[]],current=currentAll.slice(0,1000),recent=[...current,...prior].sort((a,b)=>(b.gameDate||'').localeCompare(a.gameDate||'')).slice(0,10),h2h=[...currentAll,...prior].filter(g=>g.opponentAbbrev===opp||g.opponent===opp).sort((a,b)=>(b.gameDate||'').localeCompare(a.gameDate||'')).slice(0,10);if(recent.length<3)continue;const props=[{key:'points',threshold:1},{key:'shots',threshold:2},{key:'shots',threshold:3},{key:'goals',threshold:1}];for(const prop of props){const r=hitRate(recent,prop.key,prop.threshold),c=hitRate(current,prop.key,prop.threshold),p=hitRate(prior,prop.key,prop.threshold),h=hitRate(h2h,prop.key,prop.threshold),rate=weightedRate([{rate:r,weight:.50},{rate:c,weight:.30},{rate:p,weight:.20}]);const evidence=[recent.length,current.length,prior.length].reduce((a,n)=>a+n,0);if(evidence<6)continue;candidates.push({name:player.name,team:player.team,position:player.position,opp,prop,rate,recent,current,prior,h2h,recentHits:recent.filter(g=>num(g[prop.key])>=prop.threshold).length,currentHits:current.filter(g=>num(g[prop.key])>=prop.threshold).length,priorHits:prior.filter(g=>num(g[prop.key])>=prop.threshold).length,h2hHits:h2h.filter(g=>num(g[prop.key])>=prop.threshold).length,evidence})}}}
