async function recentTeamGames(team,slateDate){const seasons=seasonIdsForDate(slateDate),responses=await Promise.all(seasons.map(async season=>{try{return(await get(`/club-schedule-season/${encodeURIComponent(team)}/${season}`)).games||[]}catch{return []}})),currentStart=Number(String(seasons[0]).slice(0,4));return [...new Map(responses.flat().filter(g=>g.gameType===2&&['OFF','FINAL'].includes(g.gameState)&&(g.gameDate||'')<slateDate).map(g=>[String(g.id),{...g,currentSeason:Number(String(g.id).slice(0,4))===currentStart}])).values()].sort((a,b)=>(b.gameDate||'').localeCompare(a.gameDate||'')).slice(0,10)}
function modelHitRate(history,key,threshold,prior){if(history.length<3)return null;const current=history.filter(g=>g.currentSeason),previous=history.filter(g=>!g.currentSeason),rate=games=>games.length?games.filter(g=>num(g[key])>=threshold).length/games.length:null,lastFive=history.slice(0,5),recent=rate(lastFive),currentRate=rate(current),previousRate=rate(previous);let baselineRate=currentRate??previousRate??prior;if(currentRate!=null&&previousRate!=null){const currentWeight=current.length/(current.length+2);baselineRate=currentRate*currentWeight+previousRate*(1-currentWeight)}const formRate=recent==null?baselineRate:recent*.55+baselineRate*.45,effectiveSample=current.length+previous.length*.65;return Math.max(.08,Math.min(.9,(formRate*effectiveSample+prior*4)/(effectiveSample+4)))}
function enumerateModelParlays(legs){const bands=[{min:2,max:2.49,label:'2× estimated return'},{min:2.5,max:2.99,label:'2.5× estimated return'},{min:3,max:3.99,label:'3× estimated return'},{min:4,max:4.99,label:'4× estimated return'},{min:5,max:7,label:'5× estimated return'}],byGame=new Map();for(const leg of legs){if(leg.probability<.12||leg.probability>.9)continue;const list=byGame.get(leg.fixtureId)||[];list.push(leg);byGame.set(leg.fixtureId,list)}const pool=[...byGame.values()].flatMap(list=>[...list.filter(x=>x.market==='Team win').sort((a,b)=>b.probability-a.probability).slice(0,1),...list.filter(x=>x.market!=='Team win').sort((a,b)=>b.probability-a.probability).slice(0,2)]).sort((a,b)=>b.probability-a.probability).slice(0,36),picks=[],seen=new Set();for(const band of bands){let best=null;for(const requireMix of [true,false]){let nodes=0;function visit(start,chosen,odds,fixtures){if(++nodes>180000)return;if(chosen.length>=2&&odds>=band.min&&odds<=band.max){const hasTeam=chosen.some(x=>x.market==='Team win'),hasPlayer=chosen.some(x=>x.market!=='Team win'),key=chosen.map(x=>x.id).sort().join('|');if((!requireMix||(hasTeam&&hasPlayer))&&!seen.has(key)&&(!best||odds<best.odds))best={band:band.label,legs:[...chosen],odds,probability:1/odds,key}}if(chosen.length===6||odds>=band.max)return;for(let i=start;i<pool.length;i++){const leg=pool[i];if(fixtures.has(leg.fixtureId))continue;const nextOdds=odds/leg.probability;if(nextOdds>band.max)continue;const nextFixtures=new Set(fixtures);nextFixtures.add(leg.fixtureId);visit(i+1,[...chosen,leg],nextOdds,nextFixtures)}}visit(0,[],1,new Set());if(best)break}if(best){seen.add(best.key);picks.push(best)}}return picks}
function renderAutoParlays(picks){$('betCombos').innerHTML=picks.length?picks.map((p,i)=>`<article class="pick-card"><span class="pick-rank">#${i+1}</span><h4>${esc(p.band)}</h4><div class="pick-rate">${p.odds.toFixed(2)}×</div><div class="pick-detail">${(100*p.probability).toFixed(1)}% model-estimated hit chance · $10 at estimated fair value: $${(10*p.odds).toFixed(2)} return</div>${p.legs.map(x=>`<div class="pick-detail" style="margin-top:8px"><b>${esc(x.market)}</b> · ${esc(x.selection)} · ${Math.round(x.probability*100)}% estimated hit rate (${x.sample} game sample; ${x.sampleDetail})</div>`).join('')}</article>`).join(''):'<div class="empty">There are not enough recent game records to form five distinct parlays for this slate.</div>'}
let autoParlayDate='',autoParlayPromise=null;
async function loadAutoDailyParlays(force=false){
 const date=$('betDate').value;
 if(autoParlayPromise)return autoParlayPromise;
 if(!force&&autoParlayDate===date)return;
 const button=$('buildBetCombos');busy(button,true,'Analyzing game history…');$('betCombos').innerHTML='';status('betStatus','Loading today’s NHL slate and recent team schedules…');
 autoParlayPromise=(async()=>{try{
  const slate=await get(`/score/${encodeURIComponent(date)}`),games=(slate.games||[]).filter(g=>!['OFF','FINAL'].includes(g.gameState));
  if(!games.length){status('betStatus','No upcoming NHL games are available for this date.');return}
  const teamAbbrevs=[...new Set(games.flatMap(g=>[g.homeTeam?.abbrev,g.awayTeam?.abbrev]).filter(Boolean))];
  const teamGames=Object.fromEntries(await Promise.all(teamAbbrevs.map(async team=>[team,await recentTeamGames(team,date)])));
  const boxscoreGames=[...new Map(Object.values(teamGames).flat().map(g=>[String(g.id),g])).values()];
  const rosterResults=await Promise.all(teamAbbrevs.map(async team=>{try{
   const data=await get(`/roster/${encodeURIComponent(team)}/current`);
   const players=[...(data.forwards||[]),...(data.defensemen||data.defense||[])].map(p=>({id:String(p.id??p.playerId),name:[p.firstName?.default||p.firstName,p.lastName?.default||p.lastName].filter(Boolean).join(' ')||p.name||'Player',team,position:p.positionCode||''})).filter(p=>p.id&&p.id!=='undefined');
   return [team,players];
  }catch{return [team,[]]}}));
  const rosters=Object.fromEntries(rosterResults),currentPlayers=new Map(Object.values(rosters).flat().map(p=>[p.id,p]));
  status('betStatus',`Reading recent game boxes for ${teamAbbrevs.length} teams…`);
  const boxscores=new Map();let cursor=0,failed=0;
  const worker=async()=>{while(cursor<boxscoreGames.length){const game=boxscoreGames[cursor++];try{boxscores.set(String(game.id),await get(`/gamecenter/${encodeURIComponent(game.id)}/boxscore`,18000))}catch{failed++}}};
  await Promise.all(Array.from({length:Math.min(8,boxscoreGames.length)},worker));
  const playerHistory=new Map();
  for(const game of boxscoreGames){const box=boxscores.get(String(game.id));if(!box)continue;const groups=box.playerByGameStats||{},rows=['awayTeam','homeTeam'].flatMap(side=>['forwards','defense'].flatMap(group=>groups[side]?.[group]||[]));
   for(const row of rows){
    const id=String(row.playerId??row.id??'');if(!currentPlayers.has(id))continue;
    const goals=num(row.goals),assists=num(row.assists),entry={date:game.gameDate||'',currentSeason:Number(String(game.id).slice(0,4))===Number(String(seasonIdsForDate(date)[0]).slice(0,4)),points:num(row.points)||goals+assists,shots:num(row.shots??row.sog),blockedShots:num(row.blockedShots??row.blocked??0)};
    const history=playerHistory.get(id)||[];history.push(entry);playerHistory.set(id,history);
   }
  }
  for(const history of playerHistory.values())history.sort((a,b)=>b.date.localeCompare(a.date));
  const legs=[];
  for(const game of games){
   const fixtureId=String(game.id),home=game.homeTeam?.abbrev,away=game.awayTeam?.abbrev;
   const recordRate=team=>{const rows=teamGames[team]||[];if(!rows.length)return .5;const wins=rows.filter(g=>{const isHome=g.homeTeam?.abbrev===team;return Number(isHome?g.homeTeam?.score??g.homeScore:g.awayTeam?.score??g.awayScore)>Number(isHome?g.awayTeam?.score??g.awayScore:g.homeTeam?.score??g.homeScore)}).length;return(wins+1)/(rows.length+2)};
   const homeRate=recordRate(home),awayRate=recordRate(away),homeLogit=(homeRate-awayRate)*2.4+.16,homeProbability=Math.max(.22,Math.min(.78,1/(1+Math.exp(-homeLogit))));
   for(const [team,probability]of [[home,homeProbability],[away,1-homeProbability]]){const rows=teamGames[team]||[],currentCount=rows.filter(g=>g.currentSeason).length;legs.push({id:`${fixtureId}:team:${team}`,fixtureId,probability,market:'Team win',selection:`${team} to win (${rows.length}-game team form)`,sample:rows.length,sampleDetail:`${currentCount} this season`})}
   const playerLegs=[];
   for(const team of [home,away])for(const player of rosters[team]||[]){
    const history=(playerHistory.get(player.id)||[]).slice(0,10);if(history.length<3)continue;
    const props=[{key:'shots',threshold:2,label:'2+ shots on goal',market:'Shots on goal',prior:.58},{key:'blockedShots',threshold:1,label:'1+ blocked shot',market:'Blocked shots',prior:.42},{key:'points',threshold:1,label:'1+ point',market:'Player points',prior:.37}];
    for(const prop of props){const probability=modelHitRate(history,prop.key,prop.threshold,prop.prior);if(probability!=null)playerLegs.push({id:`${fixtureId}:${player.id}:${prop.key}`,fixtureId,probability,market:prop.market,selection:`${player.name} · ${prop.label} (${team})`,sample:history.length,sampleDetail:`${history.filter(g=>g.currentSeason).length} this season`})}
   }
   legs.push(...playerLegs.sort((a,b)=>b.probability-a.probability).slice(0,12));
  }
  const picks=enumerateModelParlays(legs);renderAutoParlays(picks);autoParlayDate=date;
  status('betStatus',`${picks.length} parlays built from NHL team and player game histories across ${boxscores.size} recent games${failed?` (${failed} game boxes unavailable)`:''}. Return multiples are statistical estimates, not sportsbook odds.`,'success');
 }catch(error){status('betStatus',error.message||'Could not build statistical parlays from NHL game data.','error')}
 finally{busy(button,false);autoParlayPromise=null}})();return autoParlayPromise;
}
